INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-319a1b57a17c0aa4ae73', 'item-50d7613a657304e91fcd', 1, '# Explore the Responsible AI Toolbox ## Instructions In this lesson you learned about the Responsible AI Toolbox, an "open-source, community-driven project to help data scientists to analyze and improve AI systems." For this assignment, explore one of RAI Toolbox''s [notebooks](https://github.com/microsoft/responsible-ai-toolbox/blob/main/notebooks/responsibleaidashboard/tabular/getting-started.ipynb) and report your findings in a paper or presentation. ## Rubric | Criteria | Exemplary | Adequate | Needs Improvement | | -------- | --------- | -------- | ----------------- | | | A paper or powerpoint presentation is presented discussing Fairlearn''s systems, the notebook that was run, and the conclusions drawn from running it | A paper is presented without conclusions | No paper is presented |', '{"knowledge_candidates":["fairness"]}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
