INSERT INTO learning_items (learning_item_id, source_document_id, source_item_key, item_type, title, language, status, assessment_eligible, evaluation_mode, metadata) VALUES ('item-6bce0cd178bda107c9ff', 'doc-26680e9f90f5569d239d', 'notebook', 'notebook_lab', 'The Effect of Dropout', 'en', 'needs_review', FALSE, 'notebook_tests', '{"assessment_eligible":false,"assessment_role":"practice_task","discovered_via":"notebook_document","evaluation_mode":"notebook_tests","mapping_method":"term_candidate_only","mastery_evidence_policy":"strong_after_validated_tests","requires_answer_review":true,"requires_knowledge_review":true}'::jsonb) ON CONFLICT (learning_item_id) DO UPDATE SET title=EXCLUDED.title, assessment_eligible=EXCLUDED.assessment_eligible, evaluation_mode=EXCLUDED.evaluation_mode, metadata=EXCLUDED.metadata;
INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-7d339af0ff4a15e010d5', 'item-6bce0cd178bda107c9ff', 1, '## The Effect of Dropout Let''s see for ourselves how dropout actually affects training. We will use MNIST dataset and a simple convolutional network to do that: We will define `train` function that will take care of all training process, including: * Defining the neural network architecture with a given dropout rate `d` * Specifying suitable training parameters (optimizer and loss function) * Doing the training and collecting the history We will then run this function for a bunch of different dropout values: Now, let''s plot validation accuracy graphs for different dropout values to see how fast the training goes: From this graph, you would probably be able to see the following: * Dropout values in the 0.2-0.5 range, you will see the fastest training the best overall results * Without dropout ($d=0$), you are likely to see less stable and slower training process * High dropout (0.8) makes things worse', '{"knowledge_candidates":["neural-networks"]}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
