INSERT INTO learning_items (learning_item_id, source_document_id, source_item_key, item_type, title, language, status, assessment_eligible, evaluation_mode, metadata) VALUES ('item-a65fd670b98484f4f91b', 'doc-7c1c8bf25a7412a9d27e', 'lab-readme', 'notebook_lab', 'Classification of Oxford Pets using Transfer Learning', 'en', 'needs_review', FALSE, 'notebook_tests', '{"assessment_eligible":false,"assessment_role":"practice_task","discovered_via":"lab_readme","evaluation_mode":"notebook_tests","mapping_method":"term_candidate_only","mastery_evidence_policy":"strong_after_validated_tests","requires_answer_review":true,"requires_knowledge_review":true}'::jsonb) ON CONFLICT (learning_item_id) DO UPDATE SET title=EXCLUDED.title, assessment_eligible=EXCLUDED.assessment_eligible, evaluation_mode=EXCLUDED.evaluation_mode, metadata=EXCLUDED.metadata;
INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-042c3e90ea352780636d', 'item-a65fd670b98484f4f91b', 1, '# Classification of Oxford Pets using Transfer Learning Lab Assignment from [AI for Beginners Curriculum](https://github.com/microsoft/ai-for-beginners). ## Task Imagine you need to develop and application for pet nursery to catalog all pets. One of the great features of such an application would be automatically discovering the breed from a photograph. In this assignment, we will use transfer learning to classify real-life pet images from [Oxford-IIIT](https://www.robots.ox.ac.uk/~vgg/data/pets/) pets dataset. ## The Dataset We will use the original [Oxford-IIIT](https://www.robots.ox.ac.uk/~vgg/data/pets/) pets dataset, which contains 35 different breeds of dogs and cats. To download the dataset, use this code snippet: ```python !wget https://www.robots.ox.ac.uk/~vgg/data/pets/data/images.tar.gz !tar xfz images.tar.gz !rm images.tar.gz ``` ## Stating Notebook Start the lab by opening [OxfordPets.ipynb](OxfordPets.ipynb) ## Takeaway Transfer learning and pre-trained networks allow us to solve real-world image classification problems relatively easily. However, pre-trained networks work well on images of similar kind, and if we start classifying very different images (eg. medical images), we are likely to get much worse results.', '{"knowledge_candidates":["classification"]}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
