INSERT INTO learning_items (learning_item_id, source_document_id, source_item_key, item_type, title, language, status, assessment_eligible, evaluation_mode, metadata) VALUES ('item-75a30d44391c3ed759f8', 'doc-18aac5ddd86520d2a957', 'notebook', 'notebook_lab', 'Body Segmentation', 'en', 'needs_review', FALSE, 'notebook_tests', '{"assessment_eligible":false,"assessment_role":"practice_task","discovered_via":"notebook_document","evaluation_mode":"notebook_tests","mapping_method":"term_candidate_only","mastery_evidence_policy":"strong_after_validated_tests","requires_answer_review":true,"requires_knowledge_review":true}'::jsonb) ON CONFLICT (learning_item_id) DO UPDATE SET title=EXCLUDED.title, assessment_eligible=EXCLUDED.assessment_eligible, evaluation_mode=EXCLUDED.evaluation_mode, metadata=EXCLUDED.metadata;
INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-f2e65c39ad66ac385f1a', 'item-75a30d44391c3ed759f8', 1, '# Body Segmentation Lab Assignment from [AI for Beginners Curriculum](https://github.com/microsoft/ai-for-beginners). In video production, for example, in weather forecasts, we often need to cut out a human image from camera and place it on top of some other footage. This is typically done using **chroma key** techniques, when a human is filmed in front of a uniform color background, which is then removed. In this lab, we will train a neural network model to cut out the human silhouette. We will be using [Segmentation Full Body MADS Dataset](https://www.kaggle.com/datasets/tapakah68/segmentation-full-body-mads-dataset) from Kaggle. Download the dataset manually from Kaggle and unzip in into current directory. Let''s see how images in the dataset look like:', '{"knowledge_candidates":["neural-networks"]}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
