INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-0330bf347eb1cf812f6a', 'item-f8f4488efd966c69a35a', 1, '# Word-level Text Generation using RNNs Lab Assignment from [AI for Beginners Curriculum](https://github.com/microsoft/ai-for-beginners). ## Task In this lab, you need to take any book, and use it as a dataset to train word-level text generator. ## The Dataset You are welcome to use any book. You can find a lot of free texts at [Project Gutenberg](https://www.gutenberg.org/), for example, here is a direct link to [Alice''s Adventures in Wonderland](https://www.gutenberg.org/files/11/11-0.txt)) by Lewis Carroll.', '{}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
