INSERT INTO learning_items (learning_item_id, source_document_id, source_item_key, item_type, title, language, status, assessment_eligible, evaluation_mode, metadata) VALUES ('item-299f9438bf3b2e41ef1f', 'doc-4339542bd57969b9b14f', 'lab-readme', 'notebook_lab', 'Training Mountain Car to Escape', 'en', 'needs_review', FALSE, 'notebook_tests', '{"assessment_eligible":false,"assessment_role":"practice_task","discovered_via":"lab_readme","evaluation_mode":"notebook_tests","mapping_method":"term_candidate_only","mastery_evidence_policy":"strong_after_validated_tests","requires_answer_review":true,"requires_knowledge_review":true}'::jsonb) ON CONFLICT (learning_item_id) DO UPDATE SET title=EXCLUDED.title, assessment_eligible=EXCLUDED.assessment_eligible, evaluation_mode=EXCLUDED.evaluation_mode, metadata=EXCLUDED.metadata;
INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-9de65ddbeda69bff164c', 'item-299f9438bf3b2e41ef1f', 1, '# Training Mountain Car to Escape Lab Assignment from [AI for Beginners Curriculum](https://github.com/microsoft/ai-for-beginners). ## Task Your goal is to train the RL agent to control [Mountain Car](https://www.gymlibrary.ml/environments/classic_control/mountain_car/) in OpenAI Environment. <img alt="Mountain Car" src="images/mountaincar.png" width="300"/> ## The Environment Mountain Car environment consists of the car trapped inside a valley. Your goal is to jump out of the valley and reach the flag. The actions you can perform are to accelerate to the left, to the right, or do nothing. You can observe position of the car along x-axis, and velocity. ## Stating Notebook Start the lab by opening [MountainCar.ipynb](MountainCar.ipynb) ## Takeaway You should learn throughout this lab that adopting RL algorithms to a new environment is often quite straightforward, because the OpenAI Gym has the same interface for all environments, and algorithms as such do not largely depend on the nature of the environment. You can even restructure the Python code in such a way as to pass any environment to RL algorithm as a parameter.', '{}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
