INSERT INTO learning_items (learning_item_id, source_document_id, source_item_key, item_type, title, language, status, assessment_eligible, evaluation_mode, metadata) VALUES ('item-dffd64b435338529fbc8', 'doc-0b2140891defefd7c561', 'notebook', 'notebook_lab', 'CartPole Skating', 'en', 'needs_review', FALSE, 'notebook_tests', '{"assessment_eligible":false,"assessment_role":"practice_task","discovered_via":"notebook_document","evaluation_mode":"notebook_tests","mapping_method":"term_candidate_only","mastery_evidence_policy":"strong_after_validated_tests","requires_answer_review":true,"requires_knowledge_review":true}'::jsonb) ON CONFLICT (learning_item_id) DO UPDATE SET title=EXCLUDED.title, assessment_eligible=EXCLUDED.assessment_eligible, evaluation_mode=EXCLUDED.evaluation_mode, metadata=EXCLUDED.metadata;
INSERT INTO learning_item_versions (learning_item_version_id, learning_item_id, version_number, stem, answer_data, explanation) VALUES ('item-version-c42756780e00e1d42d65', 'item-dffd64b435338529fbc8', 1, '## CartPole Skating > **Problem**: If Peter wants to escape from the wolf, he needs to be able to move faster than him. We will see how Peter can learn to skate, in particular, to keep balance, using Q-Learning. First, let''s install the gym and import required libraries: ## Create a cartpole environment To see how the environment works, let''s run a short simulation for 100 steps. During simulation, we need to get observations in order to decide how to act. In fact, `step` function returns us back current observations, reward function, and the `done` flag that indicates whether it makes sense to continue the simulation or not: We can get min and max value of those numbers: ## State Discretization Let''s also explore other discretization method using bins: Let''s now run a short simulation and observe those discrete environment values. ## Q-Table Structure ## Let''s Start Q-Learning! ## Plotting Training Progress From this graph, it is not possible to tell anything, because due to the nature of stochastic training process the length of training sessions varies greatly. To make more sense of this graph, we can calculate **running average** over series of experiments, let''s say 100. This can be done conveniently using `np.convolve`: ## Varying Hyperparameters and Seeing the Result in Action Now it would be interesting to actually see how the trained model behaves. Let''s run the simulation, and we will be following the same action selection strategy as during training: sampling according to the probability distribution in Q-Table: ## Saving result to an animated GIF If you want to impress your friends, you may want to send them the animated GIF picture of the balancing pole. To do this, we can invoke `env.render` to produce an image frame, and then save those to animated GIF using PIL library:', '{"knowledge_candidates":["q-learning"]}'::jsonb, NULL) ON CONFLICT (learning_item_id, version_number) DO NOTHING;
INSERT INTO evaluation_specs (evaluation_spec_id, learning_item_version_id, evaluation_mode, evidence_policy, spec_version, config, status) VALUES ('evaluation-spec-77aeefbb449e3c67b7e0', 'item-version-c42756780e00e1d42d65', 'notebook_tests', 'strong', 1, '{"runner":"unconfigured","execute_in_sandbox":true,"requires_validated_tests":true,"checks":["execution_success","hidden_tests","output_invariants"]}'::jsonb, 'draft') ON CONFLICT (learning_item_version_id, spec_version) DO NOTHING;
